/* ---- list [байты] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_Ly { dan_hdr h; int64_t len, cap; dan_bytes *items; };

static void dl_Ly_destroy(dan_hdr *h) {
    dl_Ly *l = (dl_Ly *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dan_bytes_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_Ly *dl_Ly_from(int64_t n, dan_bytes const *src) {
    dl_Ly *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_Ly_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dan_bytes));
    for (int64_t i = 0; i < n; i++) l->items[i] = dan_bytes_share(src[i]);
    return l;
}

static void dl_Ly_push(dl_Ly *l, dan_bytes v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dan_bytes));
    }
    l->items[l->len++] = dan_bytes_share(v);
}

static dan_bytes dl_Ly_get(const dl_Ly *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dan_bytes *dl_Ly_at(dl_Ly *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_Ly_set(dl_Ly *l, int64_t i, dan_bytes v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dan_bytes old = l->items[i];
    l->items[i] = dan_bytes_share(v);
    dan_bytes_release(old);
    (void)old;
}

static void dl_Ly_write(const dl_Ly *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dan_write_bytes(l->items[i]);
    }
    putchar(']');
}

static void dl_Ly_insert(dl_Ly *l, int64_t i, dan_bytes v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_Ly_push(l, v);
    dan_bytes last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dan_bytes));
    l->items[i] = last;
}

static void dl_Ly_remove(dl_Ly *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dan_bytes old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dan_bytes));
    l->len--;
    dan_bytes_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_Ly *dl_Ly_copy(const dl_Ly *l) {
    return dl_Ly_from(l->len, l->items);
}

static inline dl_Ly *dl_Ly_share(dl_Ly *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_Ly_release(dl_Ly *l) { if (l) dan_hdr_release(&l->h, dl_Ly_destroy); }
static inline void dl_Ly_give(dl_Ly *l) { if (l) dan_hdr_give(&l->h, dl_Ly_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_Ly *dl_Ly_mut(dl_Ly **pp) {
    dl_Ly *l = *pp;
    if (l->h.rc > 1) {
        dl_Ly *r = dl_Ly_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_Ly *dl_Ly_reversed(const dl_Ly *l) {
    dl_Ly *r = dl_Ly_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dan_bytes t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_Ly *dl_Ly_slice(const dl_Ly *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_Ly_from(b - a + 1, l->items + a);
}

static dan_str dl_Ly_str(const dl_Ly *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dan_bytes_show(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_Ly_find(const dl_Ly *l, dan_bytes b) {
    for (int64_t i = 0; i < l->len; i++) { dan_bytes a = l->items[i]; if (dan_bytes_eq(a, b)) return i; }
    return -1;
}
static bool dl_Ly_contains(const dl_Ly *l, dan_bytes b) { return dl_Ly_find(l, b) >= 0; }
static bool dl_Ly_eq(const dl_Ly *x, const dl_Ly *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dan_bytes a = x->items[i]; dan_bytes b = y->items[i]; if (!(dan_bytes_eq(a, b))) return false; }
    return true;
}


