/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_Dib *dm_Dib_copy(const dm_Dib *d) {
    dm_Dib *r = dm_Dib_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_Dib_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = DAN_ID(d->keys[e]); r->vals[m] = DAN_ID(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_Dib_reindex(r);
    return r;
}
static dm_Dib *dm_Dib_mut(dm_Dib **pp) {
    dm_Dib *d = *pp;
    if (d->h.rc > 1) { dm_Dib *r = dm_Dib_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_Dib_str(const dm_Dib *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_int_to_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_bool_to_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
